-- Rebrand application-owned entity references without changing login emails, addresses, URLs or stored file paths.
START TRANSACTION;
UPDATE `app_options` SET `value`=REGEXP_REPLACE(REGEXP_REPLACE(`value`, '(?i)\\bTQ\\b', 'AC'), '(?i)\\bTestQ\\b', 'Atlis Cloud') WHERE `value` REGEXP '(?i)\\b(TQ|TestQ)\\b' AND group_key IN ('business_entity','entity_reminder_email');
